<script setup lang="ts">
import {computed,ref} from 'vue'
import {ArrowDown,ArrowLeft,ArrowUp,Check,Search,Trash2} from 'lucide-vue-next'
import type {Question} from '../api'
type Form={title:string;description:string;subject:string;grade:string;collectionType:'topic'|'paper'|'question_type'|'mixed';topicLabel:string;price:number;questionIds:string[]}
const props=defineProps<{questions:Question[];initial:Form;editing?:boolean;saving?:boolean}>()
const emit=defineEmits<{(e:'close'):void;(e:'save',value:Form):void}>()
const form=ref<Form>(JSON.parse(JSON.stringify(props.initial))),query=ref(''),typeFilter=ref('全部题型'),paperFilter=ref('全部试卷')
const types=computed(()=>['全部题型',...new Set(props.questions.map(q=>q.type).filter(Boolean))])
const papers=computed(()=>['全部试卷',...new Set(props.questions.map(q=>q.sourceTitle||q.paperId))])
const paperStats=computed(()=>papers.value.map(name=>({name,count:name==='全部试卷'?props.questions.length:props.questions.filter(q=>(q.sourceTitle||q.paperId)===name).length})))
const available=computed(()=>props.questions.filter(q=>(paperFilter.value==='全部试卷'||(q.sourceTitle||q.paperId)===paperFilter.value)&&(typeFilter.value==='全部题型'||q.type===typeFilter.value)&&(!query.value||`${q.number} ${q.stem}`.toLowerCase().includes(query.value.toLowerCase()))))
const selected=computed(()=>form.value.questionIds.map(id=>props.questions.find(q=>q.id===id)).filter(Boolean) as Question[])
function toggle(id:string){const i=form.value.questionIds.indexOf(id);i<0?form.value.questionIds.push(id):form.value.questionIds.splice(i,1)}
function move(i:number,d:number){const j=i+d;if(j<0||j>=form.value.questionIds.length)return;[form.value.questionIds[i],form.value.questionIds[j]]=[form.value.questionIds[j],form.value.questionIds[i]]}
</script>
<template>
 <div class="assembly-page">
  <header><button @click="emit('close')"><ArrowLeft/>返回试题集</button><div><b>{{editing?'编辑试题集':'组装试题集'}}</b><small>跨试卷选择已校正题目，建立专题、整卷或题型精选</small></div><button class="save" :disabled="saving||!form.title.trim()||!selected.length" @click="emit('save',form)">{{saving?'保存中…':`保存试题集（${selected.length}题）`}}</button></header>
  <section class="assembly-config">
   <label>组装类型<select v-model="form.collectionType"><option value="topic">知识专题</option><option value="paper">完整试卷</option><option value="question_type">题型专题</option><option value="mixed">混合精选</option></select></label>
   <label>专题/范围名称<input v-model="form.topicLabel" placeholder="例如：几何专题、函数专题、选择题专项"/></label>
   <label>试题集名称<input v-model="form.title" placeholder="用于商店展示的标题"/></label><label>学科<input v-model="form.subject"/></label><label>年级<input v-model="form.grade"/></label><label>售价<input v-model.number="form.price" type="number" min="0" step="0.01"/></label>
   <label class="desc">内容介绍<input v-model="form.description" placeholder="适用对象、难度、内容特色"/></label>
  </section>
  <main>
   <aside class="source-papers"><div class="source-title"><span>SOURCE PAPERS</span><h3>来源试卷</h3><p>只展示已完成校正的题目</p></div><div class="paper-sources"><button v-for="paper in paperStats" :key="paper.name" :class="{active:paperFilter===paper.name}" @click="paperFilter=paper.name"><i>PDF</i><span><b>{{paper.name}}</b><small>{{paper.count}} 道已校正题目</small></span><em>{{paper.count}}</em></button></div></aside>
   <section class="library"><div class="pane-head"><div><span>QUESTION LIBRARY</span><h3>{{paperFilter==='全部试卷'?'全部已校正题目':paperFilter}}</h3><p>当前显示 {{available.length}} 道题，可跨试卷连续选择</p></div><div class="filters"><label><Search/><input v-model="query" placeholder="搜索题干或题号"/></label><select v-model="typeFilter"><option v-for="type in types" :key="type">{{type}}</option></select></div></div><div class="question-list"><button v-for="q in available" :key="q.id" :class="{picked:form.questionIds.includes(q.id)}" @click="toggle(q.id)"><i><Check v-if="form.questionIds.includes(q.id)"/></i><strong>{{q.number}}</strong><span><b>{{q.type}} <em v-if="q.figureUrls?.length">含图</em></b><small>{{q.stem}}</small><small class="source-line">{{q.sourceTitle||'来源试卷'}} · {{q.sourceGrade||form.grade}}</small></span><mark>{{form.questionIds.includes(q.id)?'已选':'选择'}}</mark></button><div v-if="!available.length" class="empty">当前试卷或筛选条件下没有已校正试题</div></div></section>
   <aside class="set-structure"><div class="pane-head"><div><span>QUESTION SET</span><h3>试题集结构</h3><p>{{form.topicLabel||'尚未填写专题名称'}}</p></div><strong>{{selected.length}}</strong></div><div class="set-summary"><b>{{form.title||'未命名试题集'}}</b><span>{{form.collectionType==='topic'?'知识专题':form.collectionType==='paper'?'完整试卷':form.collectionType==='question_type'?'题型专题':'混合精选'}} · {{form.subject}} · {{form.grade}}</span></div><div class="selected-list"><article v-for="(q,i) in selected" :key="q.id"><span>{{i+1}}</span><div><b>第 {{q.number}} 题 · {{q.type}}</b><small>{{q.sourceTitle||q.paperId}} · {{q.stem}}</small></div><nav><button :disabled="i===0" @click="move(i,-1)"><ArrowUp/></button><button :disabled="i===selected.length-1" @click="move(i,1)"><ArrowDown/></button><button class="remove" @click="toggle(q.id)"><Trash2/></button></nav></article><div v-if="!selected.length" class="empty">从左侧试卷中选择题目</div></div></aside>
  </main>
 </div>
</template>
<style scoped>
